import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    records = list(reader)
    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    width = max(2, len(columns))
    columns = (columns + [""] * width)[:width]

    rows = []
    for record in records[1:]:
        if len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        else:
            record = record + [""] * (width - len(record))
        rows.append(record)

    return {"columns": columns, "rows": rows}
